-- Users Table
CREATE TABLE IF NOT EXISTS `users` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `password` VARCHAR(100) NOT NULL,
  `avatar` VARCHAR(255) DEFAULT NULL,
  `points` INT DEFAULT 0,
  `streak_days` INT DEFAULT 0,
  `current_book` VARCHAR(20) DEFAULT 'CET4',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Study Logs (Heatmap)
CREATE TABLE IF NOT EXISTS `study_logs` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `user_id` BIGINT NOT NULL,
  `activity_type` VARCHAR(50) NOT NULL COMMENT 'VOCAB, EXAM',
  `points_earned` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_user_created` (`user_id`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Achievements
CREATE TABLE IF NOT EXISTS `achievements` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(100) NOT NULL,
  `icon` VARCHAR(100) DEFAULT NULL,
  `condition_desc` VARCHAR(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- User Achievements
CREATE TABLE IF NOT EXISTS `user_achievements` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `user_id` BIGINT NOT NULL,
  `achievement_id` BIGINT NOT NULL,
  `earned_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uk_user_achievement` (`user_id`, `achievement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- User Words (Notebook)
CREATE TABLE IF NOT EXISTS `user_words` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL,
  `word` varchar(255) NOT NULL,
  `translate` varchar(500) DEFAULT NULL,
  `phonetic` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==========================================
-- Word Books (Enriched Structure)
-- Mapped from JSON fields: 
-- accent -> phonetic
-- mean_cn -> translate
-- mean_en -> definition_en
-- sentence -> example_en
-- sentence_trans -> example_cn
-- word_etyma -> mnemonic
-- cloze -> cloze
-- ==========================================

CREATE TABLE IF NOT EXISTS `cet4_word` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `word` VARCHAR(100) NOT NULL,
  `phonetic` VARCHAR(100),
  `translate` TEXT,
  `definition_en` TEXT,
  `example_en` TEXT,
  `example_cn` TEXT,
  `mnemonic` TEXT,
  `cloze` VARCHAR(255),
  `tags` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `cet6_word` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `word` VARCHAR(100) NOT NULL,
  `phonetic` VARCHAR(100),
  `translate` TEXT,
  `definition_en` TEXT,
  `example_en` TEXT,
  `example_cn` TEXT,
  `mnemonic` TEXT,
  `cloze` VARCHAR(255),
  `tags` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `graduate_word` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `word` VARCHAR(100) NOT NULL,
  `phonetic` VARCHAR(100),
  `translate` TEXT,
  `definition_en` TEXT,
  `example_en` TEXT,
  `example_cn` TEXT,
  `mnemonic` TEXT,
  `cloze` VARCHAR(255),
  `tags` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

