INSERT INTO `achievements` (`name`, `icon`, `condition_desc`) VALUES 
('First Step', 'seedling', 'Complete your first study session'),
('Word Master', 'trophy', 'Learn 100 words'),
('Streak Keeper', 'fire', 'Maintain a 7-day streak');
INSERT INTO `cet4_word` (`word`, `phonetic`, `translate`, `definition_en`, `example_en`, `example_cn`, `mnemonic`, `cloze`) VALUES
('well-known', '/ˌwel ˈnəʊn/', 'adj.有名的，著名的；众所周知的', 'known about by a lot of people; (of a fact) generally known and accepted', 'This is a well-known painting.', '这幅画世界闻名。', '', ''),
('develop', '/dɪˈveləp/', 'v.逐渐形成，逐渐养成；开发，研制；发展，壮大；患病', 'to gradually grow or become bigger', 'It''s said it takes 21 days to develop a new habit.', '据说养成一个新习惯需要21天。', 'de不 + velop盖上 → 不阻止，不掩盖 → develop发展', 'de-v[el]-op'),
('hamburger', '/ˈhæmbɜːrɡər/', 'n.汉堡包', 'finely chopped beef made into a flat round shape that is then fried', 'He often eats a hamburger for lunch.', '他午餐一般会吃一个汉堡包。', 'ham火腿 + burger汉堡包 → hamburger汉堡包，汉堡', 'ham-b[ur]g-er'),
('present', '"/ˈprezənt/', 'v.呈现，展现；带来；  adj.现在的，当下的；  n.现在，目前', 'to show or describe something/somebody in a particular way', 'The picture presents different ways that signals can travel to our devices.', '这幅图展示了信号传输到我们设备的各种方式。', 'pres前 + ent名词后缀 → present礼物，赠送物', 'pres[en]t'),
('outdoor', '/ˈaʊtdɔːr/', 'adj.室外的，野外的', 'used', 'Many people enjoy outdoor activities in their leisure time.', '很多人喜欢在空闲时间进行户外活动。', 'out外，出 ＋ door门 → outdoor户外的', 'out-d[oor]'),
('delicious', '/dɪˈlɪʃəs/ ', 'adj.美味的，可口的', 'having a very pleasant taste or smell; extremely pleasant or enjoyable', 'The rice noodles my brother is cooking look so delicious!', '我哥哥煮的米粉看起来真美味！', 'de再 + lic诱惑 + ious表形容词 → 再引诱的 → delicious美味的，可口的', 'De-li-ci[ou]s'),
('bitter', '/ˈbɪtər/', 'adj.严寒的', 'having a strong and often unpleasant taste; not sweet', 'The man is trying to warm his hand in this bitter cold.', '这个男人正尝试着在严寒中暖手。', '', 'bitt[er]'),
('yard', '/jɑːrd/', 'n.院子，庭院', 'a piece of land next to or around your house where you can grow flowers', 'My yard is full of flowers and plants.', '我的院子里种满了花花草草。', '', 'y[ar]d'),
('keep', '/kiːp/', 'v.继续；保持；保留', 'to continue having or holding (something) :to not return', 'She keeps studying even at bedtime.', '就算到睡觉时间了，她也继续学习。', '', 'k[ee]p'),
('museum', '/mjuˈziːəm/', 'n.博物馆，博物院，展览馆', 'a building in which objects of artistic', 'There are many pieces of art in the museum.', '博物馆里有很多艺术作品。', 'muse文艺、音乐 + um名词后缀，表场所 → museum博物馆', 'mu-s[e]-um'),
('besides', '/bɪˈsaɪdz/', 'prep.除……之外（还）', 'in addition to somebody/something; apart from somebody/something', '"As the winner', '作为胜利者，我除了得到奖杯外，还获得了一大笔钱。', 'be构成介词 + side边 + s表副词 → besides此外，而且', 'be-sid[e]s'),
('singular', '/ˈsɪŋɡjələr/', 'adj.单独的，单个的；非凡的，显著的', 'being a single and separate person or thing', 'There is a singular red flower amongst a bed of yellow ones.', '在黄色的花丛中有一朵红色的花。', 'singul=single单一 + ar……的 → singular单独的', 'sin-gu-l[ar]'),
('idea', '/aɪˈdiːə/', 'n.想法，主意；思想，概念', 'a plan', 'He came up with a good idea to solve that problem.', '他想到了一个好主意来解决那个问题。', '', 'id[ea]'),
('land', '/lænd/', 'n.陆地，土地；大地；  v.（使）着陆，降落；（使）登陆', 'the surface of the earth that is not sea', 'Who owns all of this land?', '谁是这块儿地的主人？', '', 'l[an]d'),
('wait', '/weɪt/', 'v.等待', 'to stay where you are or delay doing something until somebody/something comes or something happens', 'She is waiting for her flight.', '她正在等她的航班。', '', 'w[ai]t'),
('camp', '/kæmp/', 'n.野营', 'to live temporarily in or as if in a tent', 'They went back to the camp after hiking.', '他们在徒步旅行后回到了营地。', 'camp=field田野 → camp营地', 'c[a]mp'),
('smile', '/smaɪl/', 'n.微笑', 'an expression on your face that makes the corners of your mouth turn up and that shows happiness', 'She has a big smile on her face.', '她露出灿烂的笑容。', '', 'smi[le]'),
('indispensable', '/ˌɪndɪˈspensəbl/', 'adj.必不可少的', 'too important to be without', 'Microelement is indispensable to people. ', '微量元素是人体必不可少的。', 'in表否定 + dis向外 + pens=pense称重 + able能...的 → 不能够按重量向外分发的 → indispensable必不可少的', '[in]-dis-pens-a[ble]'),
('England', '/ˈɪŋɡlənd/', 'n.英格兰，英国', 'a division of the United Kingdom', 'London is located in the south-east of England.', '伦敦位于英格兰东南部。', '', ''),
('pork', '/pɔːrk/', 'n.猪肉', 'meat from a pig that has not been cured (= preserved using salt or smoke)', 'I bought some pork from the supermarket.', '我从超市买了些猪肉。', '', 'p[or]k'),
('development', '/dɪˈveləpmənt/ ', 'n.发展；成长；壮大', 'the gradual growth of something so that it becomes more advanced', 'This picture shows the development of phones over time.', '这张图展示了电话发展变化的历程。', 'develop发展 + ment名词后缀 → development发展', 'de-v[el]-op-m[en]t'),
('cough', '/kɔːf/', 'n.咳嗽；  v.咳嗽', 'to force out air suddenly and noisily through your throat', 'He is having a really bad cough.', '他的咳嗽很厉害。', '', 'c[ough]'),
('heavy', '/ˈhevi/', 'adj.程度深的；沉重的；大量的', 'great in yield', 'The heavy snow made walking very difficult.  ', '大雪使走路变得非常困难。', '', 'h[ea]vy'),
('marriage', '/ˈmærɪdʒ/', 'n.结婚；婚姻', 'the ceremony in which two people become husband and wife; the state of being married', 'They are holding a wedding in celebration of their marriage.', '他们正在举办一场婚礼，庆祝他们结婚。', 'marri=marry结婚 + age状态，总称 → marriage结婚', 'marria[ge]'),
('beside', '/bɪˈsaɪd/', 'prep.在……旁边', 'next to or at the side of somebody/something', 'The loyal dog is lying beside its owner.', '这只忠诚的狗正趴在主人旁边。', 'be构成介词 + side旁边 → beside在……旁边', 'b[e]-side'),
('ticket', '/ˈtɪkɪt/', 'n.票，券；证明（书）', 'a printed piece of paper that gives you the right to travel on a particular bus', 'They got two tickets to fly back.', '他们有两张返程的机票。', '', 'ti[ck]-et'),
('before', '/bɪˈfɔːr/', 'prep.在……以前（时间）；在……前面（空间）；  adv.以前；  conj.在……之前（时间）；到...为止', 'used to say that somebody/something is in a position in front of somebody/something', 'You should wash your hands before dinner.', '晚餐之前要洗手。', 'be在 + fore在前的 → before在…以前', 'be-f[ore]'),
('themselves', '/ðəmˈselvz/', 'pron.他/她/它们自己', 'used when people or animals performing an action are also affected by it', 'The old couple are holding a photo of themselves taken 50 years ago.', '这对老夫妻正拿着一张他们自己在50年前拍的照片。', '"them他们+selves自己的复数 → 他们自己', '[th]em-selves'),
('upon', '/əˈpɑːn/', 'prep.在……上面', 'in or into a position covering', '"Once upon a time', '从前有座山，山上有座庙。', 'up向上 + on在...上面 → upon在...上面', 'up-[on]'),
('while', '/waɪl/', 'conj.当……的时候，在...期间；然而；虽然；  n.一段时间', 'at the same time as something else is happening', 'The boy is playing a game while his roommate is reading a book.', '男孩玩游戏的时候，他的室友正在看书。', '', 'whi[le]'),
('sometimes', '/ˈsʌmtaɪmz/', 'adv.有时，间或', 'occasionally rather than all of the time', 'Sometimes I go to work on my bike.', '我有时会骑车上班。', 'sometime某一时间的 ＋ s表副词 → 某一时间 → sometimes有时', 'som[e]-times'),
('him', '/hɪm/', 'pron.（宾格）他', 'used as the object of a verb', 'The teacher is pointing at him.', '老师正指着他。', '', 'h[i]m'),
('me', '/miː/', 'pron.（宾格）我', 'the form of I that is used when the speaker or writer is the object of a verb or preposition', 'Who is the little boy in the photo? It''s me.', '照片上的小男孩是谁？是我。', '', 'm[e]'),
('punishment', '/ˈpʌnɪʃmənt/', 'n.惩罚，处罚', 'the act of punishing someone or a way of punishing someone', 'No criminal will escape their due punishment.', '任何罪犯都无法逃脱应有的惩罚。', 'punish惩罚 + ment表名词 → punishment处罚', 'pun-i[sh]-ment'),
('scar', '/skɑːr/', 'n.伤疤，伤痕', 'a mark that is left on the skin after a wound has healed', 'There is a scar on the boy''s face.', '次郎的脸上有一道疤痕。', '', 'sc[ar]'),
('splash', '/splæʃ/', 'v.泼洒，溅，使成斑驳状', '(of liquid) to fall noisily onto a surface', 'She splashes cold water onto her face.', '她把冷水泼到脸上。', '', 'spla[sh]'),
('pop', '/pɑp/', 'v.突然出现；爆开', 'to make a short explosive sound; to cause something to make this sound; to burst', 'I hate the mails that keep popping up.', '我讨厌那些不断弹出的邮件。', '', 'p[o]p'),
('wish', '/wɪʃ/', 'v.希望，想要；祝愿', 'a desire or a feeling that you want to do something or have something', 'They wish everything would go well.', '他们希望一切顺利。', '', 'wi[sh]'),
('bound', '/baʊnd/', 'adj.受约束的，（在法律或道德上）有义务的', 'forced to do something by law', 'She is bound to take care of her parents.', '她有照顾父母的义务。', '', 'b[ou]nd'),
('applicable', '/ˈæplɪkəbl/', 'adj.适用的，合适的，可应用的', 'capable of being applied; relevant or appropriate.', 'These tools are applicable for this job. ', '这些工具适用于这个工作。', 'ap一再+plic重叠、折叠+able能... → applicable适用的', ''),
('circuit', '/ˈsɜːrkɪt/', 'n.电路，线路；巡游', 'the complete path of wires and equipment along which an electric current flows', 'The electrician checks the electric circuit.', '电工在检查电路。', 'circu圆，环 + it走 → 环行 → 环行；电路', 'cir-c[ui]t'),
('stake', '/steɪk/ ', 'n.风险', 'something (such as money) that you could win or lose in a game', 'The doctor told them the stake was high.', '医生告诉他们风险很高。', '', 'st[a]ke'),
('hydrogen', '/ˈhaɪdrədʒən/', 'n.氢，氢气', 'a chemical element. Hydrogen is a gas that is the lightest of all the elements. It combines with oxygen to form water.', 'The balloons are filled with hydrogen in order to ascend to the air.', '为了让气球飞到空中，我们给气球充的是氢气。', 'hydro水 + gen产生 → hydrogen氢', 'hy-dro-[ge]n'),
('hedge', '/hedʒ/', 'n.篱笆，树篱', 'a row of bushes or small trees planted close together', 'The man is trimming the green hedge.', '这个男人正在修剪绿绿的树篱。', '', 'he[dge]'),
('fetch', '/fetʃ/', 'v.取来', 'to go to where somebody/something is and bring them/it back', '"\\"Here', '我一边扔球一边喊道：“小狗，取回来！”', 'fet=fed脚 + ch → 跑腿 → fetch取来', 'fe[tch]'),
('abnormal', '/æbˈnɔːrml/', 'adj.反常的', 'different from what is usual or expected', 'It''s very abnormal for a sheep to be pink!', '粉红色的羊太反常了！', 'ab相反，变坏，离去 + normal正常的 → abnormal反常的', 'ab-nor-m[al]'),
('mechanically', '/məˈkænɪkli/', 'adv.机械地', ' in a mechanical manner; by a mechanism', 'This claw is mechanically driven to pick up dolls. ', '这个爪子靠机械驱动来抓起娃娃。', '', ''),
('rational', '/ˈræʃənl/', 'adj.理性的，理智的；合理的', '(of behaviour', 'She remained rational in the face of a heavy workload.', '她在面对繁重的工作时依然保持理智。', 'ration定量，计算 + al……的 → 通过计算的 → rational合理的', 'ra-tio-n[al]'),
('contrast', '"/ˈkɑnˌtræst/', 'n.对照，对比；  v.对照，对比（读作/kənˈtræst/）', 'to compare two things in order to show the differences between them; to show a clear difference when close together or when compared', 'The contrast between before and after her makeup is obvious.', '她化妆的前后对比很明显。', 'contra相反 + st站 → 站在对立面 → contrast对比', 'con-[tr]ast'),
('unite', '/juˈnaɪt/', 'v.团结，联合', 'to make people or things join together to form a unit; to join together', 'Let''s unite as a team and win this game!', '让我们联合起来打赢这场比赛！', 'uni一个，单一 + te动词后缀，促成 → unite团结，合并', 'u-nit[e]'),
('event', '/ɪˈvent/', 'n.事件，大事；活动（指演出、体育比赛、聚会等）', 'one of the races or competitions in a sports programme', 'The "911 incident" was an event that shocked the world.', '“911事件”震惊了全世界。', 'e向外 + vent到来 → event事件 ', 'ev[en]t'),
('campaign', '/kæmˈpeɪn/', 'n.（社会性、政治性）活动，运动', 'a series of planned activities that are intended to achieve a particular social', 'They are having a campaign for the election.', '他们正在进行竞选活动。', 'camp营地 + aign名词后缀 → 营地 → 战役', 'cam-p[ai]gn'),
('reduce', '/rɪˈduːs/', 'v.减少，减小，降低', 'to make something less or smaller in size', 'The price of this phone is reduced to ¥998 in the sale.', '这款手机的价格在促销中降至998元。', 're向后 + duc引导 → 向后引导 → reduce减少；缩小；降低', 'r[e]-duce'),
('finding', '/ˈfaɪndɪŋ/', 'n.发现，调查结果', 'information that is discovered as the result of research into something', 'Her finding is beneficial to the medical field.', '她的发现对医学领域大有裨益。', 'find发现 + ing构成抽象名词 → finding发现；调查的结果', 'f[ind]-ing'),
('intention', '/ɪnˈtenʃn/', 'n.目的，意图', 'what you intend or plan to do; your aim', '"I have an intention of buying a house', '我一心想买房，所以我现在必须开始存钱了。', 'intent意图 + ion表名词 → 有意图做某事 → intention有意图，故意', 'in-ten-t[io]n'),
('republic', '/rɪˈpʌblɪk/', 'n.共和国，共和政体', 'a country that is governed by a president and politicians elected by the people and where there is no king or queen', 'France is a republic.', '法国是一个共和国。', 're事情，事务 + public公众  → 与公众相关的事务  → republic共和国', 're-p[u]b-lic'),
('accommodation', '/əˌkɑːməˈdeɪʃn/', 'n.住处，停留处', 'somewhere to live or stay', 'Her accommodation during her travel is a nice hotel.', '她旅行期间的住处是一间不错的酒店。', 'accommodat(e)使适应，容纳 + ion名词后缀 → accommodation住所', 'accommo-da-t[ion]'),
('regulation', '/regjəˈleɪʃən/', 'n.规章，法规，条例；调整，调节', 'an official rule made by a government or some other authority', 'The traffic police is introducing traffic rules and regulations to us.', '交警在向我们介绍交通法规。', 'regul规则、统治 + ation表名词 → 有规则的 → regulation规则，规章', 're-gu-l[a]-t[ion]'),
('register', '/ˈredʒɪstər/ ', 'v.登记', 'to record your/somebody’s/something’s name on an official list', 'The athletes are registering for a half-marathon around the park.', '运动员们正在登记，报名参加环绕公园的半程马拉松。', 're回 + gist携带 + er → register注册', 're-gis-t[er]'),
('forbid', '/fərˈbɪd/', 'v.禁止', 'to order somebody not to do something; to order that something must not be done', 'We forbid smoking in the restaurant.', '餐厅内禁止吸烟。', 'for反对；相反 + bid要求 → forbid禁止', 'f[or]-bid'),
('spoil', '/spɔɪl/', 'v.毁坏', 'to give a child everything that they ask for and not enough discipline in a way that has a bad effect on their character and behaviour', 'The two stupid dogs spoiled my Saturday.', '这两条傻狗毁了我的周六。', '', 'sp[oi]l'),
('bucket', '/ˈbʌkɪt/', 'n.水桶，（有提梁的）桶', 'an open container with a handle', 'She pours a bucket of water on her head to cool off.', '她往头上倒了一桶水，凉快一下。', '', 'bu[ck]-et'),
('debate', '/dɪˈbeɪt/', 'n.辩论；讨论，争论', 'In a debate two or more speakers express opposing views and then there is often a vote on the issue; a formal discussion of an issue at a public meeting or in a parliament', 'The debate begins.', '辩论开始了。', 'de否定，相反 + bat打，击 + e → 持对方相反的观点而与之进行口头上的攻击 → 反驳，辩论', 'de-b[a]te'),
('solution', '/səˈluːʃən/', 'n.解决办法；溶液', 'a way of solving a problem or dealing with a difficult situation', 'I think the other plan is a better solution.', '我觉得另一个方案是更好的解决办法。', 'solut解开；溶解 + ion名词后缀，构成抽象名词 → 溶解；解决', 'so-lu-t[ion]'),
('gradually', '/ˈɡrædʒuəli/', 'adv.逐渐地，逐步地', 'slowly', '"Gradually', '渐渐地，他变得越来越强壮。', 'gradual逐步的 + ly…...地 → gradually逐步地', 'gra-du-[all]y'),
('fame', '/feɪm/', 'n.名声，声誉', 'the condition of being known or recognized by many people', 'The actor enjoys fame and loves the attention it brings him.', '这位男演员沉浸在名望中，并享受着由此带来的关注度。', '', 'f[a]me'),
('indignant', '/ɪnˈdɪɡnənt/', 'adj.愤慨的，愤愤不平的', 'feeling or showing anger and surprise because you think that you have been treated unfairly', '"Upon finding the door firmly shut', '吃了闭门羹，她非常愤慨。', 'in不 + dign值得，高贵 + ant具有……性质的 → 不高贵的 → indignant愤慨的，愤怒的', '[in]-dig-nant'),
('theoretical', '/ˌθiːəˈretɪkl/', 'adj.理论（上）的', 'concerned with the ideas and principles on which a particular subject is based', 'He always does things on the basis of books; it is so theoretical.', '他总是按书上说的做，这太理论化了。', 'theore=theory理论 + t + ical……的 → theoretical理论（上）的', '[th]e-o-re-ti-c[al]'),
('logic', '/ˈlɑːdʒɪk/', 'n.逻辑，推理', 'a way of thinking or explaining something', 'Speaking with clear logic allows people to understand your ideas better.', '讲话逻辑清晰能让人们更好地理解你的想法。', 'log说话 + ic名词后缀 → 说话的学问 → logic逻辑学', 'log-[i]c'),
('dialog', '/ˈdaɪəlɔːɡ/', 'n.对话（=dialogue）', 'conversations in a book', 'The two sides entered into a peace dialog.', '双方进行了一次和平对话。', 'dia穿过，之间 + log说话 → dialog对话', ''),
('dynamic', '/daɪˈnæmɪk/', 'adj.动态的；不断变化的', '(of a person) having a lot of energy and a strong personality', 'Stock changes are dynamic.', '股票变化是动态的。', 'dynam=power，表示“力量” + ic…的 → dynamic有活力的', 'dy-n[a]m-ic'),
('salary', '/ˈsæləri/ ', 'n.工资，薪水', 'money that employees receive for doing their job', 'They are receiving their monthly salary from Lord Bao.', '他们正在包大人那儿领每月工资。', 'sal盐 + ary名词后缀 → salary工资（古代工钱以盐多少计算）', 's[al]ary'),
('spray', '/spreɪ/', 'v.喷', '(especially in compounds) a substance that is forced out of a container such as an aerosol', 'She is spraying some air freshener.', '她正在喷一些空气清新剂。', '', 'spr[ay]'),
('racket', '/ˈrækɪt/', 'n.球拍', 'a piece of sports equipment used for hitting the ball', 'The tennis racket is lying on the ground.', '这把网球拍被放在地面上。', '', 'ra[ck]-et'),
('cube', '/kjuːb/', 'n.立方体，立方', 'a solid or hollow figure with six equal square sides; a piece of something', 'A cube is a three-dimensional square.', '立方体是个三维正方体。', '', 'cub[e]'),
('fatigue', '/fəˈtiːɡ/', 'n.疲乏，劳累', 'a feeling of being extremely tired', '"Due to heavy fatigue', '我很疲劳，所以直接趴桌上睡着了。', 'fat断裂 + ig做，驱动 + ue动词后缀 → fatigue快断裂的，接近极限点的 → fatigue疲乏，劳累', 'fa-ti[gue]'),
('orchestra', '/ˈɔːrkɪstrə/', 'n.管弦乐队', 'a large group of people who play various musical instruments together', 'The orchestra is playing in a big theater.', '这支管弦乐队正在大剧院里演奏。', 'orches舞蹈 + tra地点 → 古希腊剧院里搞歌唱配乐的人站的地方，引申为搞配乐的一群人 → n.管弦乐队', '[or]-ches-tra'),
('prosperity', '/prɑːˈsperəti/', 'n.繁荣，兴旺，发达', 'the state of being successful', 'The prosperity of the city is evident from this busy nighttime scene.', '这忙碌的夜景显示着这座城市的繁荣。', 'prosper繁荣 + ity表名词 → prosperity繁荣昌盛', 'pros-p[e]-r[i]-ty'),
('statement', '/ˈsteɪtmənt/ ', 'n.声明', 'a formal or official account of facts or opinions; something that you say or write that gives information or an opinion', 'He is making a statement to the press.', '他正在向新闻界发表一份声明。', 'state陈述 + ment表名词 → 站着说话 → statement声明立场', 'state-m[e]nt'),
('swan', '/swɑːn/', 'n.大天鹅', 'a large bird that is usually white and has a long thin neck. Swans live on or near water.', 'There are two elegant white swans in the lake.', '湖里有两只优雅的白天鹅。', '', 'sw[an]'),
('creep', '/kriːp/', 'v.爬行', '(of people or animals) to move slowly', 'The cat is slowly creeping towards her.', '那只猫慢慢地悄悄爬向她。', '', 'cr[ee]p'),
('separate', '"/ˈseprət/', 'v.使分开，分离；  adj.独立的', 'to divide into different parts or groups; to divide things into different parts or groups;  to move apart; to make people or things move apart; to be between two people', 'The wooden fence separates the villa from the lawn.', '木栅栏将别墅与草坪分隔开了。', 'separ分离 + ate形容词后缀具有...的 → separate分离的；个别的', 'se-p[a]-rate'),
('alternative', '/ɔːlˈtɜrnətɪv/', 'n.可供选择的事物；  adj.可供选择的', 'that can be used instead of something else', 'He has the alternative of either riding or driving.', '他可以在骑车或开车中选择一种。', 'altern另外的 + ative形容词/名词后缀 → alternative替换的，替换物', '[al]-t[er]-na-tive'),
('sparrow', '/ˈspæroʊ/', 'n.麻雀', 'a small brown and grey bird', '"Sparrows are small brown and grey birds', '麻雀是一种棕灰色的小鸟，常见于世界上很多地方。', '', 'sp[ar]row'),
('drag', '/dræɡ/', 'v.拖，拉，拽，扯', 'to pull somebody/something along with effort and difficulty', 'You can drag this picture from this folder to the other.', '你可以把图片从这个文件夹拖进另一个文件夹里。', '', 'dr[a]g'),
('upright', '/ˈʌpraɪt/', 'adv.直立地', 'placed in a vertical position', 'Only a few animals other than humans are able to stand upright.', '除了人类以外，只有很少一些动物可以直立。', 'up向上 ＋ right直 → upright垂直的，正直的', 'up-r[igh]t'),
('adopt', '/əˈdɑːpt/ ', 'v.采纳，采用', 'to take somebody else’s child into your family and become its legal parent(s)', 'China is adopting the three-child policy now.', '中国目前采用三孩政策。', 'ad做…，加强… + opt选择 → 选出来 → adopt采纳，收养', '[a]dopt'),
('survive', '/sərˈvaɪv/ ', 'v.生存，活着；  v.存活；幸存', 'to continue to live or exist', 'It''s hard for plants to survive in the desert.', '对植物来说，在沙漠里生存下来很困难。', 'sur超过 + vive活 → survive存活', 's[ur]-vive'),
('frequent', '"/ˈfrikwənt/', 'adj.时常的，频繁的（读作/ˈfrikwənt/）；  v.常去，常到（读作/friˈkwent/）', 'happening or doing something often', 'Rain is frequent in this place.', '这个地方经常下雨。', 'frequ挤在一起 + ent形容词后缀 -> frequent时常的，频繁的', 'fre-[que]nt'),
('reality', '/riˈæləti/', 'n.现实，实际；事实', 'the true situation and the problems that actually exist in life', 'The photo without filter makes me realize the reality.', '没有滤镜的照片使我认清了现实。', 'real真实的 + ity名词后缀 → reality现实，真实', 're-[a]-l[i]-ty'),
('condition', '/kənˈdɪʃən/', 'n.状况，状态；条件；环境，形势', 'the circumstances or situation in which people live', 'She is in a bad condition and must stay at the hospital.', '她现在身体状况很差所以必须留在医院治疗。', 'con和，一起 + dit说 +ion名词后缀 → condition状况，形势', 'con-di-t[ion]'),
('nonsense', '/ˈnɑːnsens/', 'n.废话，胡说', 'ideas', 'What you''re saying is nonsense.', '你说的话就是胡话。', 'non无 + sense感觉，意义 → nonsense无意义', 'n[on]-sense'),
('romantic', '/roʊˈmæntɪk/', 'adj.有关情爱的，爱情的；浪漫的', 'connected or concerned with love or a sexual relationship;', 'They are at the early stage of their romantic relationship.', '他们正处在爱情关系的早期。', 'roman浪漫 + tic……的 → romantic浪漫的', 'ro-m[an]-tic'),
('drunk', '/drʌŋk/', 'adj.喝醉了的', 'having drunk so much alcohol that it is impossible to think or speak clearly', 'A drunk man passed out on the sofa.', '一个喝醉的男人在沙发上昏睡过去。', '', 'dru[nk]'),
('weakness', '/ˈwi:knəs/', 'n.（性格、系统的）弱点', 'difficulty in resisting something/somebody that you like very much', 'Vampires'' weakness is that they are afraid of sunshine.', '吸血鬼的弱点是害怕阳光。', 'weak虚弱的 + ness表名词 → weakness懦弱，虚弱', 'w[ea]k-ness'),
('classification', '/ˌklæsɪfɪˈkeɪʃn/', 'n.分类，归类', 'the act or process of putting people or things into a group or class (= of classifying them)', 'Please sort your garbage into different classifications.', '请把垃圾分成不同的类别。', 'class类别 + ifi = fy使... + cation表名词 → classify分类 + cation表名词 → 分类法', 'classi-f[i]-ca-t[ion]'),
('total', '/ˈtoʊtl/', 'n.总数；  adj.总的，全部的；完全的', 'being the amount or number after everyone or everything is counted or added together', 'It costs 500 dollars in total.', '这一共花费了500美金。', 'tot全部 + al表形容词 → total总体的', 'to-t[al]'),
('retain', '/rɪˈteɪn/', 'v.保持，保留，保存', 'to keep something; to continue to have something; to continue to hold or contain something;', 'Hot water can retain its heat for hours in the vacuum cup.', '热水能在保温杯里保持温度好几个小时。', 're回 + tain握住 → 拿回来 → retain保留', 're-t[ai]n'),
('brighten', '/ˈbraɪtn/', 'v.（使）变亮', 'to become or make something lighter or brighter in colour', 'The candle brightens her face.', '蜡烛照亮了她的脸庞。', 'bright明亮的 + en 使变成... → 明亮；变亮；活跃', 'br[igh]t-en'),
('directly', '"/daɪˈrektli/', 'adv.直接地，径直地', 'in a direct line or manner', 'Why take the long way while you can walk directly to the company?', '既然你能径直走去公司，为什么还要绕远路？', 'di使...变成 + rect直 + ly…地 → direct直接的 + ly...地 → 直接地', 'di-r[e]ct-ly');
INSERT INTO `cet4_word` (`word`, `phonetic`, `translate`, `definition_en`, `example_en`, `example_cn`, `mnemonic`, `cloze`) VALUES
('strawberry', '/ˈstrɔːberi/', 'n.草莓', 'a soft red fruit with very small yellow seeds on the surface', 'I want to buy one box of strawberries.', '我想买一盒草莓。', 'straw草 + berry浆果 → strawberry草莓', 'straw-b[er]ry'),
('complaint', '/kəmˈpleɪnt/', 'n.怨言，投诉', 'a reason for not being satisfied; a statement that somebody makes saying that they are not satisfied', 'The customer made a complaint to the manager.', '顾客向经理投诉。', 'com全部 + plaint抱怨 → 对全部东西抱怨 → complaint抱怨', 'com-pl[ai]nt'),
('liquid', '/ˈlɪkwɪd/', 'n.液体，液态物；  adj.液体的，液态的', 'a substance that flows freely and is not a solid or a gas', '"Liquid', '液体，比如说水，可以自由地流动。', 'liqu湿 + id表形容词 → liquid流体的，液态的', 'liq-[ui]d'),
('melt', '/melt/', 'v.熔化；融化', 'to become or make something become liquid as a result of heating', 'The metal is completely melted.', '金属完全被熔化了。', 'mel软 + t → 变软 → 融化', 'm[el]t'),
('acquaintance', '/əˈkweɪntəns/', 'n.相识的人，熟人', 'a person that you know but who is not a close friend', 'He met an old acquaintance at his friend''s wedding.', '他在朋友的婚礼上遇见了一位老熟人。', 'acquaint熟悉 + ance名词后缀 → acquaintance认识，熟人', 'ac-qu[ai]n-tance'),
('lighten', '/ˈlaɪtn/', 'v.照亮', 'to become or make something become brighter or lighter in colour', 'That lamp really lightens the room!', '台灯着实照亮了这个房间！', 'light光亮 + en表动词 → lighten发亮', 'l[igh]t-en'),
('soccer', '/ˈsɑːkər/', 'n.足球', 'a game played by two teams of 11 players', 'My favorite sport is soccer.', '我最喜欢的运动是足球。', '', 'socc[er]'),
('radiate', '/ˈreɪdieɪt/', 'v.辐射，发出（光或热）', 'if something radiates heat', 'The sun radiates light and heat towards the earth.', '太阳向地球发出光和热。', 'radi光线 + ate造成、使之成…… → radiate辐射，（使）从中心发散', 'ra-d[i]-ate'),
('similarly', '/ˈsɪmələrli/', 'adv.类似地，相似地', 'in almost the same way; used to say that two facts', 'The group of teenagers are dressed similarly.', '这群年轻人的穿着很相似。', 'similar相似的 + ly表副词 → similarly相似地', 'si-m[i]-l[ar]-ly'),
('daily', '/ˈdeɪli/', 'adj.每日的，日常的；  adv.每日，每天，天天', 'happening', 'I like to read the daily paper every morning.', '我喜欢在每天早上读日报。', 'dai日子，白天 + ly副词后缀 → daily每日的，日常的', 'd[ai]-ly'),
('zoo', '/zuː/', 'n.动物园', 'a place where many kinds of wild animals are kept for the public to see and where they are studied', 'There are so many animals in the zoo!', '动物园里有好多动物啊！', '', 'z[oo]'),
('awake', '/əˈweɪk/', 'adj.醒着的；  v.（使）醒来', 'not asleep (especially immediately before or after sleeping)', '"It\\u0027s already 3:22 a.m.', '现在已经是凌晨3点22分了，但她还醒着。', 'a加强意义 + wake醒着 → awake唤醒，使醒', '[aw]ake'),
('beyond', '/bɪˈjɑːnd/', 'adv.超出；  prep.超出；除…之外', 'on or to the further side of something; later than a particular time; more than something; used to say that something is not possible; too far or too advanced for somebody/something', 'He is looking at the stars and beyond.', '他在看星星以及更远的地方。', 'be强调 + yond那边 → 超过', 'be-y[o]nd'),
('dictate', '"/dɪkˈteɪt/', 'v.规定', 'to say words for somebody else to write down', 'When I was a child my mom would dictate what I ate.', '我小的时候，妈妈会规定我吃什么。', 'dict说话，断言 + ate动词后缀 → 说话 → dictate口授，命令；听写', 'dic-t[a]te'),
('selection', '/sɪˈlɛkʃən/', 'n.挑选，选择', 'a number of people or things that have been chosen from a larger group; a collection of things from which something can be chosen', 'Talent selection sometimes isn''t an easy thing.', '人才选择有时并非易事。', 'se分开 + lect选择，收集 → select分开选=选择 + ion表名词 → 选择', 'se-lec-t[ion]'),
('succeed', '/səkˈsiːd/', 'v.成功，达到目的', 'to achieve something that you have been trying to do or get; to have the result or effect that was intended; to be successful in your job', 'I succeeded! Everyone is happy for me!', '我成功了！每个人都为我开心！', 'suc在…下面 + ceed走 → 从下走到上面 → succeed成功', 'succ[ee]d'),
('semester', '/sɪˈmestər/', 'n.学期', 'one of the two periods that the school or college year is divided into', 'There are two semesters in a school year.', '一学年有两个学期。', 'se=sex六 + mester=mensis月  → 六个月（约一个学期）  → semester学期', 'se-mes-t[er]'),
('awfully', '/ˈɔːfli/', 'adv.十分，非常，很', 'very; extremely', '"Whereas the first two arms show minor injuries', '前两只手臂只是一点轻伤，最下面这只手臂伤得很可怕。', 'awful可怕的 + ly副词后缀 → awfully可怕地', '[aw]-fully'),
('queue', '/kjuː/', 'v.排队等候；  n.队，行列', 'to wait in a line of people', 'They queue up for lunch after the roles they played have been killed.', '他们扮演的角色死亡之后，演员正排着队去领便当。', 'que=cue尾巴 + ue → 形成尾巴状的一条 → queue行列，排队', '[que]ue'),
('explosion', '/ɪkˈsploʊʒn/', 'n.爆炸', 'the sudden violent bursting and loud noise of something such as a bomb exploding; the act of deliberately causing something to explode', 'The firework explosion was amazing.', '烟花爆炸的场景真是一场视觉盛宴。', 'explo(de)爆炸 + sion名词后缀 → explosion爆炸', 'ex-plo-s[ion]'),
('independence', '/ˌɪndɪˈpendəns/', 'n.（人的）自立；（国家的）独立', '(of a country) freedom from political control by other countries', 'You love independence? You must enjoy being alone.', '你喜欢独立？ 你一定很享受独自一人待着喔。', 'in不 + depend依靠 + ence名词后缀 → 不依靠 → independence独立，自主', 'in-de-p[en]-d[en]ce'),
('cage', '/keɪdʒ/', 'n.笼，鸟笼；囚笼', 'a structure made of metal bars or wire in which animals or birds are kept', 'The bird is in the cage.', '笼子里有只鸟。', '', 'ca[ge]'),
('sole', '/soʊl/', 'adj.唯一的；独有的；  n.脚底，鞋底，袜底；  v.给（鞋）换底', 'only; single', 'The sole survivor of the fire was the match in the middle.', '这场大火中唯一的“幸存者”就是中间那根火柴。', 'sol单独 ＋ e → sole单独的，唯一的', 'sol[e]'),
('indication', '/ˌɪndɪˈkeɪʃn/', 'n.迹象', 'a remark or sign that shows that something is happening or what somebody is thinking or feeling', 'The footprints are indications that an animal has been here.', '这些脚印是动物曾经来过的迹象。', 'in向内，进入 + dic说话，断言 + ation名词后缀 → 指示，指出，表示', '[in]-di-ca-t[ion]'),
('season', '/ˈsiːzn/', 'n.季（电视或电影节目）；季（节）；度假旺季', 'one of the four periods (spring', 'She is going to watch the latest season of the show.', '她准备看最新一季的节目。', 'sea播种 + son → 影响播种的时间 → season季节', 's[ea]-son'),
('machine', '/məˈʃiːn/ ', 'n.机器，机械装置', 'a piece of equipment with moving parts that does work when it is given power from electricity', 'You can use this machine to make coffee.', '你可以用这台机器冲咖啡。', 'mach机器 + ine表名词 → machine机器', 'ma-ch[in]e'),
('danger', '/ˈdeɪndʒər/', 'n.危险，（坏事或不快之事发生的）可能性', 'the possibility of something happening that will injure', 'This sign warned us that we were in danger.', '这个指示牌警告我们有危险。', 'dan(g)房子，家庭 + er名词后缀，表人或物 → 家庭抵御危险(法语传入) → danger危险', 'dan-[ge]r'),
('glad', '/ɡlæd/', 'adj.高兴的，愉快的；乐意的', 'pleased; happy', 'I am glad to be sharing my speech with you today.', '很高兴今天能给大家做演讲。', '', 'gl[a]d'),
('tempt', '/tempt/', 'v.诱惑', 'to attract somebody or make somebody want to do or have something', 'The squirrel is easily tempted by the acorn.', '这只松鼠很容易被一颗橡子引诱。', '', 't[e]mpt'),
('listen', '/ˈlɪsn/', 'v.听，倾听', 'to pay attention to somebody/something that you can hear', 'They are listening to music.', '他们正在听音乐。', 'list听 + en动词后缀 → listen听，倾听', 'lis-t[en]'),
('watch', '/wɑːtʃ/', 'v.观看，注视', 'a device that shows what time it is and that you wear on your wrist or carry in a pocket', 'She is watching TV at home.', '她在家正在看电视。', '', 'wa[tch]'),
('join', '/dʒɔɪn/', 'v.加入，成为……的一员；参加', 'to fix or connect two or more things together', 'The girl joined the discussion.', '这个女孩加入了讨论。', '', 'j[oi]n'),
('dry', '/draɪ/', 'adj.干的，干旱的；  v.变干', 'not wet', 'These flowers are dry but still beautiful.', '这些花干了也挺漂亮。', '', 'd[r]y'),
('welcome', '/ˈwelkəm/', 'v.欢迎；  adj.受欢迎的', 'to say hello to somebody in a friendly way when they arrive somewhere', 'He stood at the door to welcome the student.', '他站在门口欢迎这位学生。', '', 'w[el]-come'),
('employ', '/ɪmˈplɔɪ/', 'v.雇用；  n.使用', 'to give somebody a job to do for payment', 'She employed a babysitter to look after her children.', '她雇了个保姆来照顾她的孩子。', 'em在……里 + ploy折叠 → employ投入，雇佣', 'em-pl[oy]'),
('Friday', '/ˈfraɪdeɪ/', 'n.星期五', 'the day of the week after Thursday and before Saturday', 'It''s finally Friday!', '终于到星期五了！', '', 'Fri-d[ay]'),
('test', '/test/', 'n.测验，测试；  v.测验，测试', 'a set of questions or problems that are designed to measure a person\\u0027s knowledge', '"If you study for the test', '如果认真准备了，考试会很简单。', '', 't[e]st'),
('instead', '/ɪnˈsted/', 'adv.代替，顶替；更换；反而', 'in place of somebody/something', 'Have some healthy food instead of hamburgers.', '吃点健康的食品，别吃汉堡包了。', 'in进入，使 + stead位置 → instead代替', 'in-st[ea]d'),
('Australian', '/ɔːˈstreɪliən/', 'adj. 澳大利亚的', 'belonging or relating to Australia', 'Kangaroos are the Australian national animals.', '袋鼠是澳大利亚的国家动物。', 'Australi澳大利亚 + an...的/人 → Australian澳大利亚的', 'Aus-tr[al]ian'),
('village', '/ˈvɪlɪdʒ/', 'n.村庄，乡村', 'a very small town located in a country area', 'I lived in a remote mountain village.', '我住在一个遥远的小山村里。', 'vill=villa茅房，别墅 + age场所，物品 → village村庄', 'villa[ge]'),
('animal', '/ˈænɪml/', 'n.动物', 'a living thing that is not a human being or plant', 'There are many kinds of animals on the Earth.', '地球上的动物种类繁多。', '', 'a-ni-m[al]'),
('study', '/ˈstʌdi/', 'n.研究；  v.学习；研究', 'to spend time learning about a subject by reading', 'They are carrying out a medical study in the lab. ', '他们正在实验室里进行医学研究。', '', 'st[u]dy'),
('run', '/rʌn/', 'v.运转，运作；跑步，奔跑', 'to move using your legs', '"The man got out of the car to buy some food', '那个人让发动机继续运转着，然后下了车去买点吃的。', '', 'r[un]'),
('August', '/ˈɔːɡəst/', 'n.八月', 'the 8th month of the year', 'Autumn usually begins in August.', '秋天一般从八月开始。', '', 'Au-g[u]st'),
('ninety', '/ˈnaɪnti/', 'num.九十', 'number 90', 'Will you live to ninety years old?', '你会活到90岁吗？', 'nine九 + ty十 → ninety九十', 'n[in]e-ty'),
('everyone', '/ˈevriwʌn/', 'pron.每个人，人人，所有人', 'every person; all people', 'Everyone in the world should care about the planet.', '世界上的每个人都应该关爱地球。', 'every每 + one一个人 → everyone每个人', 'ev[er]y-one'),
('fourth', '/fɔːrθ/', 'num.第四的，第四个的，四分之一的', '4th', 'This is my fourth birthday.', '这是我四岁的生日。', 'four四 ＋ th第…/…分之一 → fourth第四，四分之一', 'f[our]th'),
('ago', '/əˈɡoʊ/', 'adv.以前', 'used in expressions of time with the simple past tense to show how far in the past something happened', 'I started going to school a few years ago.', '我几年前就上学了。', '', 'a-g[o]'),
('anybody', '/ˈenibɑːdi/', 'pron.任何人', 'any person at all; it does not matter who', 'He is taller than anybody else present.', '他比在场的其他任何人都高。', 'any任何 + body身体 → anybody任何人', '[an]y-body'),
('ninth', '/naɪnθ/', 'num.第九', '9th', 'I got my nine gifts on my ninth birthday.', '我在九岁生日时得到了9份礼物。', '', 'nin[th]'),
('yet', '/jet/', 'adv.尚，还，仍然；  conj.但是', 'used in negative sentences and questions to talk about something that has not happened but that you expect to happen', '"I\\u0027m tired', '我很累，但还没学完。', '', '[ye]t'),
('on', '/ɑːn/', 'prep.在……上；由...支撑着；关于，就......；  adj.发生', 'in or into a position covering', 'There''s a phone on the desk.', '桌上有一部手机。', '', '[on]'),
('when', '/wen/', 'conj.在……的时候', '(used in questions) at what time; on what occasion', 'The boy was watching TV when his mother came in.', '当他妈妈进来的时候，那个男孩正在看电视。', '', 'wh[en]'),
('which', '/wɪtʃ/', 'pron.哪个，哪几个，……的，……那个', 'used in questions to ask somebody to be exact about one or more people or things from a limited number; used to be exact about the thing or things that you mean; used to give more information about something', 'The teacher asked the girl which pen was hers.', '老师问女孩哪一支笔是她的。', '', 'wh[i]ch'),
('somehow', '/ˈsʌmhaʊ/', 'adv.出于某种原因，不知怎么地；以某种方式', 'in a way that is not known or certain; for a reason that you do not know or understand', 'He looked different somehow.', '不知怎么的，他看上去变了。', '', 'some-h[ow]'),
('trunk', '/trʌŋk/', 'n.象鼻', 'the long', '"Look', '看，大象正在用它的象鼻喷水。', '', 'tru[nk]'),
('awkward', '/ˈɔːkwərd/', 'adj.尴尬的', 'making you feel embarrassed', 'It was awkward when he farted in the library.', '他在图书馆放了个屁，真是尴尬。', 'awk错误方向 + ward朝向 → 转错方向 → awkward尴尬的', 'awk-w[ar]d'),
('project', '"/ˈprɑːdʒekt/', 'n.项目，工程，习作项目；  v.预计', 'a planned piece of work that is designed to find information about something', 'The engineers are discussing the construction project.', '工程师们正在讨论这个建筑工程。', 'pro向前，在前 + ject扔 → 扔向前面 → project投射', 'pro[j]ect'),
('ceremony', '/ˈserəmoʊni/', 'n.典礼', 'a public or religious occasion that includes a series of formal or traditional actions', 'The student was awarded her certificate during the graduation ceremony.', '这位毕业生在毕业典礼上被授予毕业证书。', '', 'ce-r[e]-m[o]-ny'),
('loyal', '/ˈlɔɪəl/', 'adj.忠心的，忠诚的', 'remaining faithful to somebody/something and supporting them or it', 'Dogs are always loyal to their owners.', '狗总是对它们的主人很忠心。', 'loy法律 + al表形容词 → loyal忠心的', 'loy-[al]'),
('nylon', '/ˈnaɪlɑːn/', 'n.尼龙，尼龙长袜', 'a very strong artificial material', '"The socks', '袜子，带子和绳子全部是用尼龙做成的。', '', 'ny-l[on]'),
('drill', '/drɪl/', 'v.钻孔；  n.训练', 'to make a hole in something', 'The worker drills into the wall.', '工人在墙上钻孔。', '', 'dr[i]ll'),
('famine', '/ˈfæmɪn/', 'n.饥荒', 'a situation in which many people do not have enough food to eat', 'These poor African kids suffer a lot from famine.', '这些可怜的非洲儿童饱受饥荒之苦。', 'fam饿 + ine表名词 → famine饥荒', 'fam[in]e'),
('balance', '/ˈbæləns/', 'n.平衡，平衡能力；余额；  v.平衡', 'the ability to keep steady with an equal amount of weight on each side of the body', 'Look! He can keep balance on that rope.', '看！他能在那根绳索上保持平衡。', 'ba=bi两个的 + lance天平刻度，盘子 → 天平的两端保持一致 → balance平衡', 'ba-l[an]-ce'),
('enforce', '/ɪnˈfɔːrs/', 'v.执行', 'to make sure that people obey a particular law or rule', 'The new parking restrictions will be strictly enforced.', '新的停车规定将被严格执行。', 'en进入 + force强大，力量 → 进入力量 → 强行', 'en-f[or]ce'),
('cucumber', '/ˈkjuːkʌmbər/', 'n.黄瓜', 'a long vegetable with dark green skin and light green flesh', 'Cucumbers are healthy and delicious.', '黄瓜健康又美味。', '', 'cu-cum-b[er]'),
('one', '/wʌn/', 'num.一，一个；  pron.某人（或事物）', 'the smallest whole number or a numeral representing this number', 'We only have one planet.', '我们只有一个星球。', '', ''),
('action', '/ˈækʃn/', 'n.行动；行为；情节', 'the process of doing something in order to make something happen or to deal with a situation; a thing that somebody does; the way a part of the body moves or functions; the mechanical parts of a piano', '"If you want to lose weight', '如果想减肥的话，要运动并采取行动。', 'act行动 + ion表行为，情况 → action行为', 'ac-t[io]n'),
('include', '/ɪnˈkluːd/', 'v.包括', '(not used in the progressive tenses) if one thing includes another', 'Our team includes seven people.', '我们队包括7人。', 'in进入 + clude关闭 → 关进去 → include包括', '[in]-clude'),
('activity', '/ækˈtɪvəti/', 'n.活动；活性', 'a thing that you do for interest or pleasure', 'They all like outdoor activities.', '他们都喜欢户外活动。', 'act行动，做 + ivity名词后缀 → 活动 → activity活动', 'ac-t[i]-v[i]-ty'),
('science', '/ˈsaɪəns/', 'n.科学', 'knowledge about the structure and behaviour of the natural and physical world', 'Physics and Chemistry are two different areas of science.', '物理和化学是科学的两个不同领域。', 'sci知道 + ence名词后缀 → science科学；学科', 'sci-[en]ce'),
('relevant', '/ˈreləvənt/', 'adj.相关的，有关的', 'having ideas that are valuable and useful to people in their lives and work', '"Before you write an essay', '在写论文之前，你都应该阅读一些相关的书籍。', 're表强调 + lev举起，减轻 + ant表形容词 → 能减轻的，起作用的 → relevant有关的；适宜的', 're-l[e]-vant'),
('object', '" /ˈɑːbdʒekt/', 'n.物体；对象', 'a thing that can be seen and touched', 'A UFO is a strange object.', 'UFO是一个奇怪的物体。', 'ob朝向 + ject扔 → object目标，物体', 'ob-[j]ect'),
('difficulty', '/ˈdɪfɪkəlti/', 'n.困难，困境；困难程度；难度', 'a problem; a thing or situation that causes problems', 'He is having difficulty holding up the board.', '他很难一直举着这块木板。', 'difficult困难的 + y表名词 → difficulty困难', 'diffi-c[u]l-ty'),
('admit', '/ədˈmɪt/', 'v.承认；允许加入', 'to agree', 'The boy admitted that he broke the vase.', '小男孩承认是他弄碎了花瓶。', 'ad去，往 + mit送，放出 → 送来 → admit许可进入', 'ad-m[i]t'),
('motion', '/ˈmoʊʃn/', 'n.运动，移动', 'the act or process of moving or the way something moves', 'The slow motion clearly shows how he dodges the bullets.', '慢动作清楚地展现了他是如何躲过子弹的。', 'mot=move移动 + ion名词后缀 → motion运动', 'mo-t[ion]'),
('trim', '/trɪm/', 'v.修剪', 'to make something neater', 'The barber is trimming the puppy''s hair to make it look neater.', '理发师给狗狗修理毛发，让它看起来更清爽。', '', 'tr[i]m'),
('staff', '/stæf/', 'n.工作人员', 'all the workers employed in an organization considered as a group', 'The staff are very friendly.', '这些工作人员非常友好。', '', 'sta[ff]'),
('signature', '/ˈsɪɡnətʃər/', 'n.签名，署名；识别标志，鲜明特色', 'your name as you usually write it', 'The boy wrote his father''s signature at the bottom of paper.', '男孩在试卷下面签下了他爸爸的名字。', 'signa=sign记号 + ture表名词 → 签名', 'sig-na-t[ure]'),
('reflect', '/rɪˈflekt/', 'v.反映；反射；显示', 'to show the image of somebody/something on the surface of something such as a mirror', 'Our face often reflects our mood.', '我们的脸可以反映出我们的心情。', 're回，向后 + flect弯曲 → 反弯曲 → reflect反射', 're-fl[e]ct'),
('wing', '/wɪŋ/', 'n.分部', 'one of the parts of the body of a bird', 'She works in the financial wing of the company.', '她在公司的财务部门工作。', '', 'w[ing]'),
('accelerate', '/əkˈseləreɪt//ekˈseləˌreɪt/', 'v.加速，增长', '(of a vehicle or person) to start to go faster', 'The car accelerated from 60 km/h to 100 km/h.', '汽车从60 km/h加速到了100 km/h。', 'ac去 + celer迅速 + ate动词后缀 → accelerate加速', 'acc[el]-er-ate'),
('native', '/ˈneɪtɪv/ ', 'adj.本地的', 'connected with the place where you were born and lived for the first years of your life; connected with the place where you have always lived or have lived for a long time; connected with the people who originally lived in a country before other people', 'The native people are wearing their own traditional clothes.', '当地人穿着自己的传统服装。', 'nat出生 + ive名词后缀 → native本地人', 'n[a]-tive'),
('headquarters', '/ˈhedkwɔːrtərz/', 'n.总部，总局', 'a place from which an organization or a military operation is controlled', 'The building is the headquarters of the family firm.', '这座大楼是该家族公司的总部。', 'head头 + quarter使驻扎 + s表地点 → 头脑聚集的地方 → 司令部；总部', 'head-qu[ar]-ters'),
('honour', '/ˈɑːnər/', 'n.光荣；尊敬；敬意；荣誉；  v.尊敬；兑现承诺', 'an award', 'Graduating from this school is a great honour.', '从该校毕业是极大的荣誉。', '', ''),
('tropical', '/ˈtrɑːpɪkl/ ', 'adj.热带的；炎热的；来自热带的', 'coming from', 'The tropical beach is a great place to relax.', '热带的海滩是一个放松的好地方。', 'tropic回归线 + al形容词后缀 → tropical热带的', 'tro-pi-c[al]'),
('lecture', '/ˈlektʃər/', 'n.讲座', 'a talk that is given to a group of people to teach them about a particular subject', 'The professor is giving a lecture on the anatomy of heart.', '教授正在讲授心脏解剖课程。', 'lect讲，读 + ure名词后缀 → 公开讲说 → lecture讲课；讲座', 'lec-t[ure]'),
('casual', '/ˈkæʒuəl/', 'adj.随便的', 'not showing much care or thought; seeming not to be worried; not wanting to show that something is important to you; without paying attention to detail', 'His clothes were too casual when compared to those of the other interviewees.', '和其他面试者相比，他的衣着过于随意了。', 'cas落下 + ual……的 → 突然降临的，不是安排好的 → casual偶然的', 'ca-su-[al]'),
('triangle', '/ˈtraɪæŋɡl/', 'n.三角形', 'a flat shape with three straight sides and three angles; a thing in the shape of a triangle', 'A triangle has three angles and three sides.', '三角形有三个角和三条边。', 'tri三 + angle角 → triangle三角形', 'tri-an-[gle]'),
('digest', '/daɪˈdʒest/', 'v.消化', 'a short report containing the most important facts of a longer report or piece of writing; a collection of short reports', 'Many parts of your body are involved in digesting food.', '你身体中有很多的部位共同参与了食物的消化过程。', 'di分离 + gest执行 → digest消化', 'di-[ge]st'),
('transportation', '/ˌtrænspərˈteɪʃn/', 'n.交通；运输；运输工具', 'a system for carrying people or goods from one place to another using vehicles', 'AI technology is being used in the transportation system.', 'AI技术正被用于交通系统当中。', 'trans转移 + port拿，运 + ation名词后缀 → 运输，运输业', 'trans-porta-t[ion]'),
('female', '/ˈfiːmeɪl/', 'adj.女性的；  n.女子', 'of the sex that gives birth to young; being a woman or a girl ', 'This is a pink symbol representing female characteristics.', '这是个代表女性特征的粉色标志。', 'fem=female女，妇女 + ale → female女的，雌性的动物；女子', 'fe-m[al]e'),
('scope', '/skoʊp/', 'n.范围', 'an instrument (such as a telescope or microscope) for looking through or watching something with', 'The teacher said this was beyond the scope of the course.', '老师说这已经超出了课程涉及的范围。', '', 'scop[e]'),
('mention', '/ˈmenʃn/', 'n.谈到，提及；  v.提到，提及', 'to write or speak about something/somebody', '"Her parents', '她的父母、朋友以及老师都被她提及了。', 'ment思考，神智 + ion名词后缀 → 有思考 → mention想到，提到', 'men-t[ion]'),
('neutral', '/ˈnuːtrəl/', 'adj.中性的；中立的', 'not supporting or helping either side in a disagreement', 'A pH value of 7 shows a neutral pH level.', 'pH值为7时，酸碱度为中性。', 'neutr=neuter中性的 + al属于……的 → 中立的；中性的', 'neu-tr[al]'),
('definite', '/ˈdefɪnət/', 'adj.明确的，肯定的', 'sure or certain; unlikely to change', 'The police found definite proof that he committed the crime.', '警方已经掌握明确证据，可以证明是他实施了犯罪。', 'defin明确 + ite形容词后缀 → definite明确的', 'de-f[i]-nite'),
('empty', '/ˈempti/', 'adj.空的；  v.倒空；腾空', 'with no people or things inside; (of something that somebody says or does) with no meaning; not meaning what is said', '"There are many seats in the meeting room', '会议室有很多座位，但是都是空的。', '', '[e]mp-ty'),
('delegation', '/ˌdelɪˈɡeɪʃn/', 'n.代表团', 'a group of people who represent the views of an organization', 'The German delegation received a warm welcome upon arrival to the UK.', '德国代表团到达英国时，受到了热烈欢迎。', 'de加强意义 + leg=to appoint任命 + ation名词后缀 → n.代表团', 'de-[le]-ga-t[ion]'),
('climb', '/klaɪm/', 'v.攀登，爬', 'to go up something towards the top; to move somewhere', 'I don''t think I could climb that mountain.', '我觉得我攀不上这座山。', '', 'cl[i]mb'),
('figure', '/ˈfɪɡjər/', 'v.想出；认为，认定；  n.数字；人影，人物；身形，身影', 'the shape or form of a person''s body', 'He finally figured out how to get there after asking a man for help.', '在询问别人之后，他终于搞清楚了该怎么去那里。', '', 'fig-[ure]');
INSERT INTO `cet4_word` (`word`, `phonetic`, `translate`, `definition_en`, `example_en`, `example_cn`, `mnemonic`, `cloze`) VALUES
('secret', '/ˈsiːkrət/', 'n.秘密', 'something that is known about by only a few people and not told to others', 'The little girl is telling her mother a secret.', '这个小女孩正在告诉她的妈妈一个秘密。', 'se分开 + cret区别 → 分开来放 → secret秘密', 's[e]-cret'),
('material', '/məˈtɪriəl/', 'n.材料，原料；素材，资料', 'a substance that things can be made from; cloth used for making clothes', 'She has prepared the cooking material for lunch.', '她已经准备好了午餐的烹饪原料。', 'mater=mother母亲，起源 + ial → 各种物品的起源 → 原材料', 'ma-t[e]-ri-[al]'),
('hello', '/həˈloʊ/', 'int.你好（打招呼用语）', 'used as a greeting when you meet somebody', '"Hello', '你好，鲍勃，你过得如何啊？', '', 'h[el]lo'),
('punch', '/pʌntʃ/', 'v.以拳痛击；  n.潘趣酒；宾治酒', 'to hit somebody/something hard with your fist (= closed hand)', 'She punched her opponent fiercely in the face.', '她用拳头猛击对手的脸。', '', 'p[un]ch'),
('ambition', '/æmˈbɪʃn/', 'n.抱负', 'the desire or determination to be successful', 'Her ambition is to become a superwoman and save the world.', '她的志向是成为一个女超人并拯救世界。', 'amb大 + it行走 + ion名词后缀 → 走大步 → ambition雄心，志向', 'am-bi-t[io]n'),
('relation', '/rɪˈleɪʃn/', 'n.关系，联系', 'the way in which two people', 'They have built a business relation; they''re partners from now on.', '他们建立了商业关系；从现在开始，他们就是合作伙伴了。', 'relat=relate关联 + ion名词后缀 → relation关系；联系；家属', 're-la-t[ion]'),
('cancer', '/ˈkænsər/', 'n.癌症', 'a serious disease caused by cells that are not normal and that can spread to one or many parts of the body', 'Smoking may cause lung cancer.', '吸烟可能会导致肺癌。', 'canc=kar艰难，严重 + er名词后缀，人或物 → 严重的疾病 → cancer癌症', 'can-c[er]'),
('guide', '/ɡaɪd/', 'n.指南，手册；导游；  v.引导，指导', 'to direct or influence somebody’s behaviour; to help somebody to move in a particular direction; to move something in a particular direction', 'She is reading the chair assembly guide to build the chair.', '她正在阅读组装这把椅子的指南。', '', 'g[ui]de'),
('cock', '/kɑːk/', 'n.公鸡', 'an adult male chicken', 'The cock has a beautiful tail.', '这只公鸡的尾巴很漂亮。', '', 'co[ck]'),
('behavior', '/bɪˈheɪvjə(r)/ ', 'n.行为（=behaviour）', 'the way that somebody behaves', 'Saying "Hello" to the teacher is a good behavior.', '向老师问好是一种好的行为。', 'be表示动作 + hav持有 + ior表名词 → 人持有的动作 → behavior举止行为', 'be-ha-v[io]r'),
('negative', '/ˈneɡətɪv/', 'adj.消极的，负面的', 'bad or harmful; considering only the bad side of something/somebody; lacking enthusiasm or hope', 'He received too many negative comments from others.', '他收到了太多负面的评价。', 'negat否认 + ive形容词后缀 → 否认的', 'ne-g[a]-tive'),
('optional', '/ˈɑːpʃənəl/', 'adj.选修的；可选择的', 'that you can choose to do or have if you want to', 'I have four optional courses this term.', '这学期我有四门选修课。', 'opt选择 + ion表名词 + al形容词后缀 → optional可任意选择的', 'op-t[io]n-al'),
('require', '/rɪˈkwaɪər/', 'v.需要；要求，规定', '(often passive) to make somebody do or have something', 'Cars require fuel if you want them to move.', '你想车子动起来的话，就需要汽油。', 're再 + quire寻求，询问 → 再寻求 → require请求', 're-qu[ire]'),
('further', '/ˈfɜːrðər/', 'adj.更进一步的；  adv.进一步', '(comparative of far) at or to a greater distance; to a greater degree or extent', 'The man has further questions for the teacher.', '这个男人有更进一步的问题要问老师。', 'furth=forth向前，向前方 + er比较级 → 更前面的 → further更远的', 'fur-[th]er'),
('lately', '/ˈleɪtli/', 'adv.最近，不久前，近来', 'recently; in the recent past', '"Lately', '最近的气温一直超过40摄氏度。', 'late最近的 + ly……地 → lately最近，不久前', 'l[a]te-ly'),
('woman', '/ˈwʊmən/', 'n.女人；  adj.女人的，女性的，妇女的', 'an adult female human', 'My grandmother is such an elegant woman!', '我的奶奶是一个多么优雅的女人啊！', '', 'wom[an]'),
('enable', '/ɪˈneɪbl/', 'v.使能够，使可能', 'to cause (a feature or capability of a computer) to be active or available for use', 'Standing on the box enables him to look out the window.', '站在箱子上让他能够看到窗外。', 'en使…进入状态 + able能够 → enable使能够', 'en-a[ble]'),
('portable', '/ˈpɔrtəbl/', 'adj.轻便的，手提的，便携式的', 'that is easy to carry or to move', 'I prefer portable computers—they''re more convenient.', '我更喜欢手提电脑——它们更方便。', 'port拿，运 + able能…的 → portable可携带的', 'porta[ble]'),
('indefinite', '/ɪnˈdefɪnət/', 'adj.不清楚的，模糊的', 'not clearly defined; lasting for a period of time that has no fixed end', 'Which door should he go through? The answer is indefinite.', '他应该通过哪扇门？答案是不确定的。', 'in无 + defin=define确定 + ite形容词后缀 → 不确定的', '[in]-de-f[i]-nite'),
('rise', '/raɪz/', 'v.升起，上升，上涨；  n.增长', 'to come or go upwards; to reach a higher level or position', 'The bright sun rises on the horizon.', '明亮的太阳从地平线上升起。', '', 'ris[e]'),
('holiday', '/ˈhɑːlədeɪ/', 'n.节日，假期，休假日；法定假日，公共节日', 'a period of time when you are not at work or school', 'We had a good time on our holiday.', '我们度过了一个愉快的假期。', 'hol神圣 + i + day日子 → holiday节假日', 'ho-li-d[ay]'),
('metal', '/ˈmetl/', 'adj.金属制的；  n.金属，合金，金属制品', 'a substance (such as gold', 'This is a metal horse.', '这是一匹金属制的马。', '', 'met-[al]'),
('sugar', '/ˈʃʊɡər/', 'n.糖', 'a sweet substance usually in the form of white or brown crystals or white powder that comes from plants and is used to make foods sweeter', 'I''d like a spoonful of sugar in my coffee.', '我想在我的咖啡里放一勺糖。', '', 'sug-[ar]'),
('light', '/laɪt/', 'v.点火，照亮；  n.光亮；  adj.轻的', 'full of light; having the natural light of day', 'She is lighting a candle.', '她正在点蜡烛。', ' ', 'l[igh]t'),
('heavily', '/ˈhevɪli/', 'adv.重重地，沉重地，沉闷地，猛烈地', 'to a great degree; in large amounts', 'The financial pressure weighed heavily on him.', '经济压力使他不堪重负。', 'heav沉重的 + i + ly副词后缀 → heavily沉重地', 'h[ea]-vi-ly'),
('practice', '/ˈpræktɪs/', 'n.做法；练习，训练；实践，实行；事务所；  v.练习（=practise）', 'to do an activity or train regularly so that you can improve your skill', 'Working from home is a good practice to keep you safe.', '在家办公是一个能保证你健康安全的好做法。', 'pract实践 + ice表名词，行为，状态 → practice实践', 'prac-tic[e]'),
('sit', '/sɪt/', 'v.坐', 'to rest your weight on your bottom with your back vertical', 'The little girl is sitting on the ground.', '小女孩坐在地上。', '', 's[i]t'),
('heart', '/hɑːrt/', 'n.心，心脏；内心；勇气', 'a kind or generous feeling for other people', 'Kind people have big hearts.', '善良的人们拥有博大的心。', '', 'h[ear]t'),
('milk', '/mɪlk/', 'n.（牛或羊等的）奶', 'the white liquid produced by cows', 'Drinking one glass of milk each day is good for your bones.', '每天喝一杯牛奶有益于你的骨骼。', '', 'm[i]lk'),
('height', '/haɪt/', 'n.高，（物的）高度；最强点；顶点', 'a measurement of how tall a person or thing is :the distance from the bottom to the top of a person or thing', 'The woman is measuring her daughter''s height.', '这个女人正在给她女儿量身高。', 'heigh=high高的 + t(h)名词后缀，宽度或深度等 → height高度', 'h[eigh]t'),
('shut', '/ʃʌt/', 'v.关上，闭上；停止，中止', 'to make something close; to become closed', '"Shut the door', '请把门关上。', '', '[sh]ut'),
('classroom', '/ˈklæsruːm/', 'n.教室，课堂', 'a room where classes are taught in a school', 'Students can have lessons in classrooms.', '学生们可以在教室里上课。', 'class班级 + room房间 → classroom教室', 'class-r[oo]m'),
('up', '/ʌp/', 'adv.起来，起床；  prep.向上，沿', 'towards or in a higher position; to or at a higher level', 'I usually get up at 7 o''clock in the morning.', '我通常早上7点钟起床。', '', '[u]p'),
('example', '/ɪɡˈzæmpl/', 'n.例子，实例，例证；模范', 'a person or way of behaving that is seen as a model that should be followed', 'The math example was completed by Mr. Li.', '这道数学例题是李老师完成的。', '"ex出 + ample拿，获得 → 拿出来作为榜样 → example 样本', 'ex-am-[ple]'),
('rich', '/rɪtʃ/', 'adj.富有的；肥沃的；丰富的；浓厚的', 'having a lot of money or property', 'The rich couple decided to sail around the world after they retired.', '这一对富裕的夫妻决定在退休后去环游世界。', '', 'R[i]ch'),
('never', '/ˈnevər/', 'adv.从不，永不', 'not ever；not at any time', '"Elephants', '大象、奶牛和猪永远不会飞。', 'ne不 + ever从来 → 从来不 → never从不', 'nev-[er]'),
('during', '/ˈdʊrɪŋ/', 'prep.在…期间', 'throughout the entire time of (an event', 'It''s rude to talk on the phone during dinner.', '在吃晚餐时打电话很没礼貌。', 'dur持久 ＋ ing构成介词 → during在…期间', 'dur-[ing]'),
('many', '/ˈmeni/', 'adj.许多的，大量的；  pron.许多人', 'consisting of or amounting to a large but indefinite number', 'I''ve wrapped so many gifts for Christmas.', '我把这么多圣诞节礼物都包好了。', '', 'm[an]y'),
('literary', '/ˈlɪtəreri/', 'adj.文学的，文学上的；以写作为职业的', 'connected with literature', 'She put many famous literary books on her bookshelf.', '她在书架上放了很多文学名著。', 'liter文字，字母 + ary形容词后缀 → literary文学的', 'lit-[er]-ary'),
('locomotive', '/ˌloʊkəˈmoʊtɪv/', 'n.机车，火车头', 'a railway engine that pulls a train', 'Old locomotives ran on coal and steam.', '老式火车靠煤和蒸汽提供动力。', 'loco地方 + mot动 + ive名词后缀 → 从一地动到一地 → locomotive火车头', 'lo-c[o]-m[o]-tive'),
('across', '/əˈkrɔːs/', 'prep.在各处，遍及；经过，穿过，越过，横跨；  adv.横过', 'from one side to the other side of something; on the other side of something;', 'He is a famous actor across the world.', '他是一位世界著名的演员。', 'a加强 + cross交叉 → across越过，横跨', '[a]cross'),
('dead', '/ded/', 'adj.死的，无生命的；停滞的，不运行的', 'no longer alive or living: no longer having life', 'The fish is dead.', '这条鱼死了。', '', 'd[ea]d'),
('first', '/fɜːrst/', 'det.第一，首要的；  adv.首先，第一；  n.第一个；最初', 'happening or coming before all other similar things or people; 1st', 'Crossing the finish line in first place is an amazing feeling.', '第一个越过终点线是一种很棒的感觉。', '', 'f[ir]st'),
('poem', '/ˈpoʊəm/', 'n.诗，韵文，诗体文', 'a piece of writing in which the words are chosen for their sound and the images they suggest', 'This great poem was written by Li Bai.', '这首名诗是李白写的。', '', 'p[o]-em'),
('postman', '/ˈpoʊstmən/', 'n.邮递员(pl. postmen)', 'a man whose job is to collect and deliver letters', 'It''s the postman with some love letters—or are they bills?', '邮递员手里拿的是情书还是账单呢？', 'post邮件，邮政 + man人 → postman邮递员', 'p[ost]-man'),
('doctor', '/ˈdɑːktər/', 'n.医生，医师，大夫；博士', 'a person who is skilled in the science of medicine :a person who is trained and licensed to treat sick and injured people', '"I want to be a doctor and save lives', '我想成为一名拯救生命的医生，但是这非常困难。', 'doct教 ＋ or表名词，人 → 教的人 → doctor博士，医生', 'doc-t[or]'),
('coffee', '/ˈkɔːfi/', 'n.咖啡', 'the roasted seeds (called coffee beans) of a tropical bush; a powder made from them', 'Coffee is a drink made with water and ground coffee beans.', '咖啡是用水和磨碎的咖啡豆制成的饮料。', '', 'coff[ee]'),
('forget', '/fərˈɡet/', 'v.忘记，遗忘', 'to be unable to remember sth that has happened in the past or information that you knew in the past', 'He forgot to remove his key from the lock when he left his apartment.', '他离开公寓时忘了把钥匙从门锁上拔下来。', 'for否定，相反 + get得到，想起 → 想不起来的 → forget忘记', 'for-[ge]t'),
('weather', '/ˈweðər/', 'n.天气；  v.平安地渡过（难关）；风化，受风蚀，经受风雨', 'the state of the air and atmosphere at a particular time and place :the temperature and other outside conditions (such as rain', 'The weather was different when we went back to that place.', '我们再回到那个地方的时候，天气不一样了。', 'we吹 + ther后缀 → 吹风等天气 → weather天气', 'wea[th]-er'),
('knee', '/niː/', 'n.膝盖', 'the joint that bends at the middle of your leg', 'The woman hurt her knee while running.', '那个女人跑步的时候弄伤了膝盖。', '', '[kn]ee'),
('mercury', '/ˈmɜːrkjəri/', 'n.水银，汞', 'a chemical element. Mercury is a poisonous silver liquid metal', 'The thermometer smashed and the mercury flowed out.', '温度计摔碎了，里面的水银流了出来。', '', 'm[er]-cury'),
('quite', '/kwaɪt/', 'adv.很，非常；的确，真正地', 'to a great degree; very; really', 'The girl in the front is quite tall compared to the girl behind.', '和后面的女孩相比，前面那个女孩相当高。', '', 'q[ui]te'),
('mission', '/ˈmɪʃən/', 'n.任务，使命', 'an important official job that a person or group of people is given to do', 'The soldiers advance to complete the mission.', '士兵们前进完成任务。', 'miss送，放出 + ion名词后缀 → 送出 → mission派遣', 'miss[ion]'),
('moan', '/moʊn/', 'v.抱怨', '(of a person) to make a long deep sound', 'He is moaning about his troubles to a friend on the phone. ', '他在打电话向朋友抱怨困扰。', '', 'm[oa]n'),
('few', '/fjuː/', 'adj.少数的；很少的，几乎没有的；  pron.少数人', 'used with plural nouns and a plural verb to mean ‘not many’', 'Sadly he finds that he has very few likes.', '令人伤心的是，他发现自己的赞很少。', '', 'f[ew]'),
('nineteen', '/ˌnaɪnˈtiːn/', 'num.十九，十九个', '19', 'I''m nineteen years old now!', '我现在十九岁啦！', 'nine九 + teen十 → nineteen十九', 'nine-t[ee]n'),
('nine', '/naɪn/', 'num.九个；九', '9', 'Nine apples are in this picture.', '图片上画了九个苹果。', '', 'n[in]e'),
('tenth', '/tenθ/', 'num.第十（的）', '10th', 'The woman pushed the tenth-floor elevator button.', '这位女士按下了第十层的电梯按钮。', '', 'ten[th]'),
('end', '/end/', 'n.末端，终点；终止，结束；  v.终止，结束', 'the final part of a period of time', 'She is at the end of the queue.', '她排在了队伍的末尾。', '', '[en]d'),
('notebook', '/ˈnoʊtbʊk/', 'n.笔记本', 'a book with blank pages that is used for writing notes', 'I like to use colorful stickers to mark the important pages in my notebook.', '我喜欢用彩色便利贴在笔记本的重要页面上做标记。', 'note笔记 + book书 → notebook笔记本，期票簿', 'note-b[oo]k'),
('your', '/jʊr/', 'det.（you的所有格）你的，您的，你们的', 'of or belonging to the person or people being spoken or written to', 'Don''t forget your umbrella. It might rain.', '不要忘了你的雨伞，可能会下雨。', '', 'y[our]'),
('rejoice', '/rɪˈdʒɔɪs/', 'v.感到欣喜，感到高兴', 'to express great happiness about something', 'They rejoiced at skating together.', '一起轮滑，他们非常高兴。', 're表强调 + joi=joy开心的 + ice名词后缀(作动词使用) → rejoice感到欣喜', 're-j[oi]ce'),
('subtract', '/səbˈtrækt/', 'v.减去，减掉', 'to take a number or an amount away from another number or amount', '"If you subtract 3 from 5', '5减去3等于2。', 'sub在下面 + tract抽 → 抽去 → 减去，去掉', 'sub-tr[a]ct'),
('surname', '/ˈsɜːrneɪm/', 'n.姓', 'a name shared by all the members of a family (written last in English names)', 'Please write your first name and surname here.', '请把你的名和姓写在这里。', 'sur超过，在上面 + name姓名 → surname用姓称呼', 's[ur]-name'),
('roll', '/roʊl/', 'v.滚动，转动', 'to turn over and over and move in a particular direction; to make a round object do this', 'They''re too fat to walk properly so they roll.', '他们肥得不能正常走路，所以只能往前滚了。', '', 'r[oll]'),
('volt', '/voʊlt/ ', 'n.伏特（电压单位）', 'a unit for measuring the force of an electric current', 'The cable has 220 volts of electricity.', '这根电线有220伏的电。', '', 'v[olt]'),
('brim', '/brɪm/', 'n.边缘', 'the top edge of a cup', 'She touched the brim of her hat.', '她摸了摸帽檐。', '', 'br[i]m'),
('assess', '/əˈses/', 'v.评估；估值', 'to make a judgement about the nature or quality of somebody/something; to calculate the amount or value of something', '"How do you assess the risk level of this investment? Low', '你对这次投资的风险评估是怎样的？低风险、中风险，还是高风险？', 'ad=as有关 + sess坐 -> 文职人员都是坐着的 -> 评估', 'a[ss]ess'),
('acceptance', '/əkˈseptəns/', 'n.接纳', 'the act or process of accepting; the state of being accepted or acceptable', 'I was excited that my proposal found general acceptance among my colleagues.', '我很兴奋，因为我的提议得到了同事们的广泛接纳。', 'ac一再+cept拿+ance→acceptance接受；承认', ''),
('attribute', '/ˈætrɪbjuːt/', 'v.把……归因于，把……归咎于（读作/əˈtrɪbjut/）', 'to say or believe that something is the result of a particular thing', 'Success can be attributed to hard work and a bit of luck.', '成功都可以归因于努力的奋斗和些许的运气。', 'at+tribut给予+e→attribute把...归因于...', ''),
('aero', '/''eroʊ/', 'adj.航空的；飞行的；飞机的', 'of or for aeronautics or aircraft', 'The two engineers are checking the aero engines.', '这两位工程师正在检查航空发动机。', '', ''),
('arise', '/əˈraɪz/', 'v.出现', 'to happen as a result of a particular situation', 'Tooth problems usually arise from eating too much sugar.', '吃太多糖通常会出现牙齿问题。', 'a加强意义 + rise升起 → arise起来，升起', '[ar]ise'),
('cafe', '/kæˈfeɪ/', 'n.咖啡馆', 'a place where you can buy drinks and simple meals. Alcohol is not usually served in British or American cafes.; a small shop/store that sells sweets', 'The man drinks coffee in a cafe.', '这个男人在咖啡馆喝咖啡。', '', ''),
('execute', '/ˈeksɪkjuːt/', 'v.处决，处死；完成（动作）；实行；执行（计划）', 'to kill somebody or something', 'This pathetic bird is going to be executed by the cruel hunter.', '这只可怜的小鸟将要被残酷的猎人处决了。', 'ex向外 + (s)ec跟随，相接 + ute → 一步接一步的执行 → 实施，将……处死', 'e-x[e]-cute'),
('elbow', '/ˈelboʊ/', 'n.手肘；衣服肘部；  v.用肘推、挤', 'the joint between the upper and lower parts of the arm where it bends in the middle', 'My elbow hurts really bad!', '我的胳膊肘伤得很重！', '', 'el-b[ow]'),
('collapse', '/kəˈlæps/', 'v.（突然）倒塌，昏倒；  n.倒塌', 'a sudden failure of something', 'The building collapsed after the earthquake.', '地震后这栋建筑倒塌了。', 'col共同 + lapse倒 → 全部倒下 → collapse倒塌', 'c[oll]apse'),
('sway', '/sweɪ/', 'v.动摇（某人）', 'to move slowly from side to side; to move something in this way', 'His huge inheritance swayed his plan to find a job.', '巨额遗产动摇了他打工的念头。', '', 'sw[ay]'),
('honesty', '/ˈɑːnəsti/', 'n.诚实；正直', 'the quality of being honest', 'The boy shows honesty by saying that he broke the vase.', '男孩说是他打碎了花瓶，体现了自己的诚实。', '', ''),
('neat', '/niːt/', 'adj.整齐的', 'not messy; clean and orderly', 'The owner kept the book shelves neat.', '这个主人把书架打理得很整齐。', '', 'n[ea]t'),
('lord', '/lɔːrd/', 'n.有爵位的贵族', '(in Britain) a man of high rank in the nobility (\\u003d people of high social class)', 'He''s an English lord honored by the King.', '他是一个被国王册封的英国贵族。', '', 'l[or]d'),
('environment', '/ɪnˈvaɪrənmənt/ ', 'n.生活或工作环境；自然环境；周围状况', 'the complete structure within which a user', 'We live in a peaceful environment.', '我们生活在一个和平安定的环境里。', 'environ包围，环绕 + ment表名词 → environment环境', 'en-v[i]-r[o]n-ment'),
('remain', '/rɪˈmeɪn/', 'link-v.保持；  v.剩余', 'to continue to be something; to be still in the same state or condition and do not change', 'Her love to play the piano has always remained unchanged.', '她对弹钢琴的热爱一直未变。', 're回 + main逗留 → 回来留下 → remain剩余', 're-m[ai]n'),
('brown', '/braʊn/', 'adj.褐色的，棕色的；  n.褐色，棕色', 'having the colour of earth or coffee', '"Her hair is brown', '她的头发是棕色的，然而她朋友的头发是黑色的。', '', 'br[ow]n'),
('refute', '/rɪˈfjuːt/', 'v.驳斥', '', 'She just wants to refute everything by saying ''no.''', '她就是通过说“不”来驳斥一切。', 're向后 + fute打，击 → refute驳斥', 'r[e]-fute'),
('chemical', '/ˈkemɪkl/', 'n.化学品，化学物质；  adj.化学的，与化学有关的', 'a substance obtained by or used in a chemical process', 'There are some colourful chemicals in the containers.', '容器里有一些五颜六色的化学品。', 'chem化学 + ical……的 → chemical化学的', 'che-mi-c[al]'),
('editor', '/ˈedɪtər/', 'n.（报刊、杂志的）编辑', 'a person who prepares a book to be published', 'The video editor is using special computer software to do his work.', '这位视频编辑正在用特殊的电脑软件工作。', 'edit编辑 + or表示人 → editor编者，编辑', 'e-di-t[or]'),
('competition', '/ˌkɑːmpəˈtɪʃn/ ', 'n.比赛，竞赛；竞争', 'a situation in which people or organizations compete with each other for something that not everyone can have', 'Who is going to win this competition?', '谁将赢得这场比赛呢？', 'compet=compete竞争 + ition名词后缀 → competition比赛', 'com-pe-t[i]-t[ion]'),
('colleague', '/ˈkɑːliːɡ/', 'n.同事', 'a person that you work with', 'The colleagues work together in the office every day.', '这些同事们每天都在办公室一起工作。', 'col共同 + league捆绑 → 捆绑在一起的人 → colleague同事', 'c[oll]eague'),
('criticism', '/ˈkrɪtɪsɪzəm/', 'n.批评', 'the act of expressing disapproval and of noting the problems or faults of a person or thing; the act of criticizing someone or something', 'The stick man took criticism from another.', '这个火柴人受到了另一个火柴人的批评。', 'critic批评者 + ism名词后缀 → criticism 批评', 'cri-t[i]-cism'),
('resolution', '/ˌrezəˈluːʃn/ ', 'n.决心，决定，坚定', 'a formal statement of an opinion agreed on by a committee or a council', 'She made a resolution to read all of these English novels in just one week.', '她下定决心要在一周内读完所有这些英文小说。', 're不 + solut松开 + ion名词后缀，构成抽象名词 → 不解决就不松开 → resolution决心；溶解', 're-so-l[u]-t[io]n'),
('photograph', '/ˈfoʊtəɡræf/', 'n.照片', 'a picture that is made by using a camera that stores images in digital form or that has a film sensitive to light inside it', 'Here are all of my travel photographs.', '这些都是我旅行拍的照片。', 'photo光 + graph写，图 → 用光写 → photograph相片', 'pho-t[o]-graph'),
('tail', '/teɪl/', 'n.尾巴', 'the part that sticks out and can be moved at the back of the body of a bird', 'The horse''s long tail lifted up into the air as it ran.', '马的长尾巴随着其奔跑的步伐甩向空中。', '', 't[ai]l'),
('composition', '/ˌkɑːmpəˈzɪʃ(ə)n/', 'n.作品', 'a piece of music or art', 'Beethoven''s compositions are great works.', '贝多芬的作曲是伟大的作品。', 'com一起 + posit放 + ion名词后缀 → 放到一起 → 组合 → composition创作、作文', 'com-po-s[i]-t[ion]'),
('gather', '/ˈɡæðər/', 'v.聚集，召集；收集，搜集', 'to come together', 'People gather around to listen to the girl''s beautiful singing.', '人们聚在一块，听女孩美妙的演唱。', '', 'ga[th]-er'),
('boast', '/boʊst/', 'v.（地方、机构等）自豪地拥有（好的事物）；吹嘘；夸耀', 'to talk with too much pride about something that you have or can do', 'The house boasts a big pool.', '这个房子有一个大泳池。', 'boa膨胀 + st → 吹牛 → boast夸耀', 'b[oa]st'),
('simplify', '/ˈsɪmplɪfaɪ/', 'v.简化', 'to make something easier to do or understand', 'The Chinese characters have been simplified for easier writing.', '为了方便书写，我们对汉字进行了简化。', 'simple简单 + -fy动词词尾 → 使简化', 'sim-pl[i]-fy'),
('monthly', '/ˈmʌnθli/', 'adj.每月的，每月一次的', 'happening', 'I have to keep up with my monthly house payments.', '我必须每月付清房租。', 'month月 + ly形容词后缀，...的 → monthly每月的', 'mon[th]-ly'),
('boil', '/bɔɪl/', 'v.烧开，煮沸，沸腾', 'when a liquid boils or when you boil it', 'As the water boils it gives off steam.', '水沸腾了，冒着水蒸气。', '', 'b[oi]l'),
('carrot', '/ˈkærət/', 'n.胡萝卜', 'the long orange root of a plant that is eaten as a vegetable', 'Look! I have collected so many carrots!', '瞧！我已经采了这么多胡萝卜！', '', 'c[ar]rot'),
('roar', '/rɔːr/', 'n.吼叫声，轰鸣声；喧闹；  v.吼叫；喧闹；  v.大声呼喊；使轰鸣', 'a loud deep sound made by an animal', 'The tiger let out a mighty roar on the cliff.', '这只老虎在山崖上发出威猛的怒吼。', '', 'r[oar]');
INSERT INTO `cet4_word` (`word`, `phonetic`, `translate`, `definition_en`, `example_en`, `example_cn`, `mnemonic`, `cloze`) VALUES
('unbearable', '/ʌnˈberəbl/', 'adj.不堪忍受的', 'too painful', 'The smell of the garbage is unbearable. Take it out!', '垃圾的味道简直让人受不了，快把它拿出去！', 'un不 ＋ bear忍受 ＋ able能...的 → unbearable难以忍受的；承受不住的', 'un-b[ear]-able'),
('minor', '/ˈmaɪnər/ ', 'adj.较小的；轻微的；  n.未成年人', 'not very large', 'It was just a minor injury.', '这只是一个小伤。', 'min小 ＋ or表物 → minor较小的；较少的', 'mi-n[or]'),
